CREATE TYPE "IntegrationEndpointStatus" AS ENUM ('ACTIVE','INACTIVE','DEGRADED','DISABLED');
CREATE TYPE "IntegrationDeliveryStatus" AS ENUM ('PENDING','RETRYING','DELIVERED','FAILED','DEAD_LETTER','CANCELLED');
CREATE TYPE "IntegrationSagaStatus" AS ENUM ('RUNNING','COMPLETED','FAILED','COMPENSATING','COMPENSATED','CANCELLED');
CREATE TABLE "IntegrationEndpoint" ("id" TEXT NOT NULL,"endpointKey" TEXT NOT NULL,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"description" TEXT,"status" "IntegrationEndpointStatus" NOT NULL DEFAULT 'ACTIVE',"configuration" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationEndpoint_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationEventDefinition" ("id" TEXT NOT NULL,"eventName" TEXT NOT NULL,"domain" TEXT NOT NULL,"version" TEXT NOT NULL,"description" TEXT,"schema" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationEventDefinition_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationEvent" ("id" TEXT NOT NULL,"eventName" TEXT NOT NULL,"aggregateType" TEXT NOT NULL,"aggregateId" TEXT,"payload" JSONB NOT NULL,"correlationId" TEXT,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IntegrationEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationWebhook" ("id" TEXT NOT NULL,"webhookKey" TEXT NOT NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"eventNames" JSONB NOT NULL,"secret" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationWebhook_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationDelivery" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"webhookId" TEXT NOT NULL,"status" "IntegrationDeliveryStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"responseBody" TEXT,"lastError" TEXT,"nextAttemptAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationDelivery_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationSaga" ("id" TEXT NOT NULL,"sagaKey" TEXT NOT NULL,"name" TEXT NOT NULL,"correlationId" TEXT,"status" "IntegrationSagaStatus" NOT NULL DEFAULT 'RUNNING',"state" JSONB NOT NULL,"error" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IntegrationSaga_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IntegrationEndpoint_endpointKey_key" ON "IntegrationEndpoint"("endpointKey"); CREATE INDEX "IntegrationEndpoint_type_status_idx" ON "IntegrationEndpoint"("type","status");
CREATE UNIQUE INDEX "IntegrationEventDefinition_eventName_key" ON "IntegrationEventDefinition"("eventName"); CREATE INDEX "IntegrationEventDefinition_domain_active_idx" ON "IntegrationEventDefinition"("domain","active");
CREATE INDEX "IntegrationEvent_eventName_occurredAt_idx" ON "IntegrationEvent"("eventName","occurredAt"); CREATE INDEX "IntegrationEvent_correlationId_idx" ON "IntegrationEvent"("correlationId");
CREATE UNIQUE INDEX "IntegrationWebhook_webhookKey_key" ON "IntegrationWebhook"("webhookKey"); CREATE INDEX "IntegrationWebhook_active_idx" ON "IntegrationWebhook"("active");
CREATE INDEX "IntegrationDelivery_status_nextAttemptAt_idx" ON "IntegrationDelivery"("status","nextAttemptAt"); CREATE INDEX "IntegrationDelivery_eventId_idx" ON "IntegrationDelivery"("eventId"); CREATE INDEX "IntegrationDelivery_webhookId_idx" ON "IntegrationDelivery"("webhookId");
CREATE UNIQUE INDEX "IntegrationSaga_sagaKey_key" ON "IntegrationSaga"("sagaKey"); CREATE INDEX "IntegrationSaga_status_updatedAt_idx" ON "IntegrationSaga"("status","updatedAt"); CREATE INDEX "IntegrationSaga_correlationId_idx" ON "IntegrationSaga"("correlationId");
ALTER TABLE "IntegrationDelivery" ADD CONSTRAINT "IntegrationDelivery_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "IntegrationEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IntegrationDelivery" ADD CONSTRAINT "IntegrationDelivery_webhookId_fkey" FOREIGN KEY ("webhookId") REFERENCES "IntegrationWebhook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
